            if (matchDialog != null && matchDialog.isShowing()) {
                matchDialog.dismiss();
                wsManager.close();
                Toast.makeText(this, "匹配超时，请检查服务器连接", Toast.LENGTH_LONG).show();
            }
        };
        timeoutHandler.postDelayed(timeoutRunnable, 15000);

        // 使用统一的用户名进行联机
        wsManager.connect(currentDifficulty, Config.getCurrentUserName());

        wsManager.setOnMessageListener(new WebSocketManager.OnMessageListener() {
            @Override
            public void onMatchFound(String opponentName) {
                runOnUiThread(() -> {
                    timeoutHandler.removeCallbacks(timeoutRunnable);
                    if (matchDialog != null && matchDialog.isShowing()) {
                        matchDialog.dismiss();
                    }
                    showMatchConfirmDialog(opponentName);
                });
            }

            @Override
            public void onRealStart() {
                runOnUiThread(() -> {
                    if (matchConfirmDialog != null && matchConfirmDialog.isShowing()) {
                        matchConfirmDialog.dismiss();
                    }
                    startGame(currentDifficulty);
                });
            }

            @Override public void onOpponentScore(int score) {}
            @Override public void onOpponentDead() {}
            @Override public void onGameOver(int p1Score, int p2Score) {}

            @Override
            public void onError(String message) {
                runOnUiThread(() -> {
                    timeoutHandler.removeCallbacks(timeoutRunnable);
                    if (matchDialog != null && matchDialog.isShowing()) matchDialog.dismiss();
                    if (matchConfirmDialog != null && matchConfirmDialog.isShowing()) matchConfirmDialog.dismiss();
                    Toast.makeText(MainActivity.this, message, Toast.LENGTH_LONG).show();
                });
            }
        });
    }

    private void showMatchConfirmDialog(String opponentName) {
        matchConfirmDialog = new AlertDialog.Builder(this)
                .setTitle("匹配成功！")
                .setMessage("对手：" + opponentName + "\n难度：" + getDiffName(currentDifficulty) + "\n准备好开始对战了吗？")
                .setPositiveButton("准备就绪", null)
                .setNegativeButton("退出", (dialog, which) -> wsManager.close())
                .setCancelable(false)
                .create();

        matchConfirmDialog.show();

        matchConfirmDialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v -> {
            wsManager.sendReady();
            matchConfirmDialog.setMessage("等待对方准备...");
            v.setEnabled(false);
        });
    }

    private String getDiffName(int diff) {
        if (diff == 1) return "简单";
        if (diff == 3) return "困难";
        return "普通";
    }

    private void startGame(int difficulty) {
        game = new Game(this, difficulty, scoreDao, soundManager, isMusicEnabled, isMultiplayer, wsManager);
        game.setOnGameOverListener(new Game.GameHolder() {
            @Override
            public void onGameOver(int score) {
                runOnUiThread(() -> { gameStop(); showScoreDialog(score); });
            }
            @Override
            public void onMultiplayerGameOver(int myScore, int opponentScore) {
                runOnUiThread(() -> { gameStop(); showMultiplayerResult(myScore, opponentScore); });
            }
        });
        setContentView(game);
        if (isMusicEnabled) soundManager.playBgm();
    }

    private void gameStop() {
        if (soundManager != null) soundManager.stopAll();
        game = null;
        showMenu();
    }

    private void showMultiplayerResult(int myScore, int opponentScore) {
        String res = myScore > opponentScore ? "你赢了！" : (myScore < opponentScore ? "你输了..." : "平局");
        new AlertDialog.Builder(this)
                .setTitle("对战结果")
                .setMessage(res + "\n你的得分: " + myScore + "\n对手得分: " + opponentScore)
                .setPositiveButton("保存成绩", (dialog, which) -> {
                    if (wsManager != null) wsManager.close();
                    showScoreDialog(myScore);
                })
                .setCancelable(false)
                .show();
    }

    private void showScoreDialog(int score) {
        if (Config.isLoggedIn) {
            // 已登录用户：自动使用用户名，不再弹输入框
            new AlertDialog.Builder(this)
                    .setTitle("游戏结束")
                    .setMessage(Config.getCurrentUserName() + "，你的最终得分: " + score + "\n记录已自动保存。")
                    .setPositiveButton("查看排行榜", (dialog, which) -> {
                        saveAndUploadScore(Config.getCurrentUserName(), score);
                    })
                    .setCancelable(false)
                    .show();
        } else {
            // 访客模式：允许输入名字
            final EditText editText = new EditText(this);
            editText.setText("访客");
            editText.setSelectAllOnFocus(true);
            new AlertDialog.Builder(this)
                    .setTitle("保存成绩")
                    .setMessage("你的得分: " + score + "\n请输入昵称：")
                    .setView(editText)
                    .setPositiveButton("确定", (dialog, which) -> {
                        String name = editText.getText().toString().trim();
                        if (name.isEmpty()) name = "访客";
                        saveAndUploadScore(name, score);
                    })
                    .setNegativeButton("不保存", (dialog, which) -> {
                        startActivity(new Intent(MainActivity.this, RankActivity.class));
                    })
                    .setCancelable(false)
                    .show();
        }
    }

    private void saveAndUploadScore(String name, int score) {
        String safeName = (name == null || name.trim().isEmpty()) ? Config.getCurrentUserName() : name.trim();
        ScoreRecord record = new ScoreRecord(safeName, score, LocalDateTime.now(), currentDifficulty);
        scoreDao.addScore(record);

        // 只有登录用户才尝试上传云端
        if (Config.isLoggedIn) {
            networkManager.uploadScore(record, new NetworkManager.OnResponseListener<>() {
                @Override
                public void onSuccess(String data) {
                    runOnUiThread(() -> {
                        Toast.makeText(MainActivity.this, "云端同步成功", Toast.LENGTH_SHORT).show();
                        startActivity(new Intent(MainActivity.this, RankActivity.class));
                    });
                }
                @Override
                public void onFailure(String error) {
                    runOnUiThread(() -> {
                        Toast.makeText(MainActivity.this, "本地已保存 (服务器离线)", Toast.LENGTH_SHORT).show();
                        startActivity(new Intent(MainActivity.this, RankActivity.class));
                    });
                }
            });
        } else {
            Toast.makeText(this, "记录已保存到本地", Toast.LENGTH_SHORT).show();
            startActivity(new Intent(MainActivity.this, RankActivity.class));
        }
    }

    @Override
    protected void onPause() { super.onPause(); if (soundManager != null) soundManager.stopAll(); }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        timeoutHandler.removeCallbacks(timeoutRunnable);
        if (wsManager != null) wsManager.close();
        if (soundManager != null) soundManager.release();
    }
}

package edu.hitsz;

import android.content.Intent;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.EditText;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import edu.hitsz.data.Config;
import edu.hitsz.data.MatchRecord;
import edu.hitsz.data.NetworkManager;
import edu.hitsz.data.ScoreDao;
import edu.hitsz.data.ScoreDaoImpl;
import edu.hitsz.data.ScoreRecord;

public class ProfileActivity extends AppCompatActivity {

    private ScoreDao scoreDao;
    private NetworkManager networkManager;
    private HistoryAdapter historyAdapter;
    private TextView tvSignature;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_profile);

        Config.loadSession(this);
        scoreDao = new ScoreDaoImpl(this);
        networkManager = new NetworkManager();

        setupUI();
        loadData();
    }

    private void setupUI() {
        tvSignature = findViewById(R.id.tv_signature);

        // 点击签名进行修改
        tvSignature.setOnClickListener(v -> showEditSignatureDialog());

        RecyclerView rvHistory = findViewById(R.id.rv_history);
        rvHistory.setLayoutManager(new LinearLayoutManager(this));
        historyAdapter = new HistoryAdapter(new ArrayList<>());
        rvHistory.setAdapter(historyAdapter);

        findViewById(R.id.btn_logout).setOnClickListener(v -> {
            Config.clearSession(this);
            startActivity(new Intent(this, LoginActivity.class));
            finishAffinity();
        });
    }

    private void showEditSignatureDialog() {
        if (!Config.isLoggedIn) {
            Toast.makeText(this, "离线访客模式下暂不支持云端签名", Toast.LENGTH_SHORT).show();
            return;
        }

        final EditText editText = new EditText(this);
        editText.setText(tvSignature.getText());
        editText.setHint("输入你的新个性签名");

        new AlertDialog.Builder(this)
                .setTitle("修改个人描述")
                .setView(editText)
                .setPositiveButton("保存", (dialog, which) -> {
                    String newSig = editText.getText().toString().trim();
                    if (!newSig.isEmpty()) {
                        updateSignatureOnServer(newSig);
                    }
                })
                .setNegativeButton("取消", null)
                .show();
    }

    private void updateSignatureOnServer(String signature) {
        networkManager.updateSignature(Config.getCurrentUserName(), signature, new NetworkManager.OnResponseListener<>() {
            @Override
            public void onSuccess(String data) {
                runOnUiThread(() -> {
                    tvSignature.setText(signature);
                    Toast.makeText(ProfileActivity.this, "描述已更新", Toast.LENGTH_SHORT).show();
                });
            }

            @Override
            public void onFailure(String error) {
                runOnUiThread(() -> Toast.makeText(ProfileActivity.this, "更新失败: " + error, Toast.LENGTH_SHORT).show());
            }
        });
    }

    private void loadData() {
        TextView tvNickname = findViewById(R.id.tv_nickname);
        tvNickname.setText(Config.getCurrentUserName());

        List<ScoreRecord> localScores = scoreDao.getAllScores();
        int maxScore = localScores.isEmpty() ? 0 : localScores.get(0).getScore();
        ((TextView) findViewById(R.id.tv_stat_streak)).setText(String.valueOf(maxScore));

        if (!Config.isLoggedIn) {
            ((TextView) findViewById(R.id.tv_signature)).setText("离线访客模式，云端资料不可用");
            historyAdapter.updateData(new ArrayList<>());
            calculateMatchStats(new ArrayList<>());
            return;
        }

        networkManager.getMatchHistory(Config.getCurrentUserName(), new NetworkManager.OnResponseListener<>() {
            @Override
            public void onSuccess(List<MatchRecord> history) {
                runOnUiThread(() -> {
                    historyAdapter.updateData(history);
                    calculateMatchStats(history);
                });
            }

            @Override
            public void onFailure(String error) {
                runOnUiThread(() -> {
                    Toast.makeText(ProfileActivity.this, "战绩加载失败，已显示本地数据", Toast.LENGTH_SHORT).show();
                    historyAdapter.updateData(new ArrayList<>());
                    calculateMatchStats(new ArrayList<>());
                });
            }
        });
    }

    private void calculateMatchStats(List<MatchRecord> history) {
        int totalMatches = history.size();
        int wins = 0;
        for (MatchRecord r : history) {
            if ("WIN".equals(r.getResult(Config.getCurrentUserName()))) wins++;
        }
        double winRate = totalMatches == 0 ? 0 : (wins * 100.0 / totalMatches);

        ((TextView) findViewById(R.id.tv_stat_matches)).setText(String.valueOf(totalMatches));
        ((TextView) findViewById(R.id.tv_stat_wins)).setText(String.valueOf(wins));
        ((TextView) findViewById(R.id.tv_stat_winrate)).setText(String.format(Locale.getDefault(), "%.1f%%", winRate));
    }

    private static class HistoryAdapter extends RecyclerView.Adapter<HistoryAdapter.ViewHolder> {
        private List<MatchRecord> records;
        HistoryAdapter(List<MatchRecord> records) { this.records = records; }
        void updateData(List<MatchRecord> newData) { this.records = newData; notifyDataSetChanged(); }

        @NonNull
        @Override
        public ViewHolder onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
            View v = LayoutInflater.from(parent.getContext()).inflate(android.R.layout.simple_list_item_2, parent, false);
            return new ViewHolder(v);
        }

        @Override
        public void onBindViewHolder(@NonNull ViewHolder holder, int position) {
            MatchRecord r = records.get(position);
            String res = r.getResult(Config.getCurrentUserName());
            holder.text1.setText(String.format("[%s] VS %s", res, r.getOpponent(Config.getCurrentUserName())));
            holder.text2.setText(String.format(Locale.getDefault(), "分数: %d - %d | 时间: %s", r.getMyScore(Config.getCurrentUserName()), r.getOpScore(Config.getCurrentUserName()), r.getTimeString()));
            if ("WIN".equals(res)) holder.text1.setTextColor(0xFF388E3C);
            else if ("LOSS".equals(res)) holder.text1.setTextColor(0xFFD32F2F);
        }

        @Override
        public int getItemCount() { return records.size(); }

        static class ViewHolder extends RecyclerView.ViewHolder {
            TextView text1, text2;
            ViewHolder(View v) { super(v); text1 = v.findViewById(android.R.id.text1); text2 = v.findViewById(android.R.id.text2); }
        }
    }
}

